SELECT issue_key, status, status_category, assignee, priority, resolution, issue_type, status_since
FROM issue_state_known_at(TIMESTAMP '2013-08-12 05:10', TIMESTAMP '2013-08-17 14:56')
WHERE issue_key = 'TAJO-118';

SELECT l.src, l.relation, l.dst
FROM links_at(TIMESTAMP '2017-12-03 00:38') l
WHERE l.src = 'TAJO-721' OR l.dst = 'TAJO-721';

SELECT subject, id, ref, status, status_category, status_since, resolution
FROM issue_state_at('apache-tajo', TIMESTAMP '2016-09-30 15:21')
WHERE subject IN ('issue:TAJO-1459', 'issue:TAJO-1461');

SELECT count(*) AS n, min(status_since) AS earliest, max(status_since) AS latest FROM issue_state_at('apache-rave', TIMESTAMP '2012-02-09 21:38');
SELECT id, ref FROM issue_state_at('apache-rave', TIMESTAMP '2012-02-09 21:38') LIMIT 5;
SELECT subject, id FROM entities WHERE id LIKE '%839%' OR subject LIKE '%839%' LIMIT 10;

SELECT l.src, l.relation, l.dst, l.valid_from, l.valid_to FROM links l WHERE l.relation='blocks' AND l.dst='RAVE-608' AND l.superseded_at IS NULL
UNION ALL
SELECT l.src, l.relation, l.dst, l.valid_from, l.valid_to FROM links l WHERE l.relation='blocks' AND l.src='RAVE-608' AND l.superseded_at IS NULL;

SELECT key, project FROM issues WHERE key ILIKE '%4228%' OR key ILIKE 'RAVE-422%';
SELECT id, type, issue_key, occurred_at FROM events WHERE issue_key ILIKE '%4228%' LIMIT 20;
SELECT project, COUNT(*) AS n, MIN(key), MAX(key) FROM issues GROUP BY project;

SELECT id, ref, summary, status, resolution, resolution_since, status_since
FROM issue_state_known_at('apache-rave', TIMESTAMP '2013-07-18 19:07', k := TIMESTAMP '2013-07-21 10:14')
WHERE ref = 'RAVE-984' OR id = 'RAVE-984';

WITH r AS (
  SELECT * FROM relations_at('apache-rave', TIMESTAMP '2014-04-29 12:47')
),
rel AS (
  SELECT src AS a, dst AS b, rel FROM r WHERE rel <> 'in_project'
),
related AS (
  SELECT b AS other FROM rel WHERE a LIKE '%RAVE-164%' OR a LIKE '%:164%'
  UNION
  SELECT a AS other FROM rel WHERE b LIKE '%RAVE-164%' OR b LIKE '%:164%'
)
SELECT * FROM related;

SELECT subject, ref, status, status_category, status_since
FROM issue_state_at('apache-rave', TIMESTAMP '2014-04-29 12:47')
WHERE subject IN ('issue:RAVE-271','issue:RAVE-298','issue:RAVE-22','issue:RAVE-165','issue:RAVE-164');

WITH t AS (SELECT TIMESTAMP '2013-12-29 18:07' AS t),
rel AS (
  SELECT r.* FROM relations_at('apache-rave', (SELECT t FROM t)) r
)
SELECT * FROM rel WHERE src LIKE '%RAVE-10%' OR dst LIKE '%RAVE-10%' OR src LIKE '%:10' OR dst LIKE '%:10';

WITH r AS (
  SELECT * FROM relations_known_at('apache-rave', TIMESTAMP '2013-12-29 18:07')
  WHERE src = 'issue:RAVE-10' OR dst = 'issue:RAVE-10'
)
SELECT src, rel, dst, valid_from, valid_to FROM r
WHERE rel <> 'in_project' AND valid_from <= TIMESTAMP '2013-12-29 18:07' AND (valid_to IS NULL OR valid_to > TIMESTAMP '2013-12-29 18:07');

SELECT subject, id, ref, status, status_category, resolution, status_since
FROM issue_state_at('apache-rave', TIMESTAMP '2013-12-29 18:07')
WHERE subject = 'issue:RAVE-10' OR ref = 'RAVE-10';

WITH r AS (
  SELECT * FROM relations_known_at('apache-rave', TIMESTAMP '2013-12-29 18:07')
  WHERE src = 'issue:RAVE-10' OR dst = 'issue:RAVE-10'
)
SELECT src, rel, dst, valid_from, valid_to FROM r
WHERE rel <> 'in_project' AND CAST(valid_from AS TIMESTAMP) <= TIMESTAMP '2013-12-29 18:07' AND (valid_to IS NULL OR CAST(valid_to AS TIMESTAMP) > TIMESTAMP '2013-12-29 18:07');

SELECT subject, ref, priority, status, assignee, resolution, issue_type, in_project
FROM issue_state_at('apache-rave', TIMESTAMP '2012-12-13 20:21')
WHERE ref = 'RAVE-509';

SELECT subject, ref, id, summary, priority, status, assignee, issue_type
FROM issue_state_known_at('apache-rave', now())
WHERE ref ILIKE '%509%';

SELECT v.subject, v.verdict
FROM stalled_verdicts('apache-rave', TIMESTAMP '2013-07-24 22:20') v
WHERE v.verdict = true;

SELECT issue_key, status, status_category, status_since
FROM issue_state_known_at(TIMESTAMP '2014-08-01 21:01', TIMESTAMP '2014-08-02 03:09')
WHERE issue_key = 'RAVE-1175';

SELECT l.src, l.relation, l.dst, l.valid_from, l.valid_to FROM links l WHERE l.relation='blocks' AND l.dst='RAVE-608' AND l.superseded_at IS NULL
UNION ALL
SELECT l.src, l.relation, l.dst, l.valid_from, l.valid_to FROM links l WHERE l.src='RAVE-608' AND l.relation='blocks' AND l.superseded_at IS NULL;

